#include <stdio.h>
#include <stddef.h>

unsigned int binary_array_to_number(const unsigned int *binary_array, size_t length) {
    unsigned int result = 0;
    for (size_t i = 0; i < length; i++) {
        result = (result << 1) | binary_array[i];
    }
    return result;
}

